if (empty($_SESSION['email']) || !ensureOrderManagementTables() || !ensureMisTables()) { header('Location: login.php'); exit; }
$conn = dbConnect(); $email = $_SESSION['email']; $orderId = max(0, (int) ($_GET['order'] ?? 0));
if (empty($_SESSION['delivery_feedback_csrf'])) $_SESSION['delivery_feedback_csrf'] = bin2hex(random_bytes(32));
if ($_SERVER['REQUEST_METHOD'] === 'POST' && hash_equals($_SESSION['delivery_feedback_csrf'], $_POST['csrf'] ?? '')) {
    $postedOrderId = (int)($_POST['orderid'] ?? 0); $action = $_POST['delivery_action'] ?? '';
    $owner = mysqli_prepare($conn, 'SELECT t.status FROM orders o JOIN order_tracking t ON t.orderid=o.orderid WHERE o.orderid=? AND o.email=? LIMIT 1'); mysqli_stmt_bind_param($owner, 'is', $postedOrderId, $email); mysqli_stmt_execute($owner); $ownedOrder = mysqli_fetch_assoc(mysqli_stmt_get_result($owner));
    if (!$ownedOrder || !in_array($ownedOrder['status'], array('delivered','completed'), true)) { $_SESSION['delivery_feedback_notice'] = 'This delivery is not ready for confirmation.'; header('Location: track-order.php?order=' . $postedOrderId); exit; }
    if ($action === 'problem') {
        $message = trim($_POST['problem_message'] ?? '');
        if ($message === '') $message = 'Customer reported a problem after delivery.';
        createSupportTicket($email, 'Delivery concern for order #' . $postedOrderId, $message, 'delivery', $postedOrderId);
