    } elseif ($action === 'confirm') {
        $food = (int)($_POST['food_rating'] ?? 0); $service = (int)($_POST['service_rating'] ?? 0); $ordering = (int)($_POST['ordering_rating'] ?? 0); $comment = trim($_POST['comment'] ?? ''); $consent = !empty($_POST['consent_to_feature']) ? 1 : 0;
        if ($food < 1 || $food > 5 || $service < 1 || $service > 5 || $ordering < 1 || $ordering > 5 || strlen($comment) > 1000) { $_SESSION['delivery_feedback_notice'] = 'Please give all three ratings and keep your comment under 1,000 characters.'; header('Location: track-order.php?order=' . $postedOrderId); exit; }
        $feedback = mysqli_prepare($conn, "INSERT INTO delivery_feedback(orderid,customer_email,receipt_confirmed,food_rating,service_rating,ordering_rating,comment,consent_to_feature,status) VALUES(?,?,1,?,?,?,?,?,'pending') ON DUPLICATE KEY UPDATE receipt_confirmed=1,food_rating=VALUES(food_rating),service_rating=VALUES(service_rating),ordering_rating=VALUES(ordering_rating),comment=VALUES(comment),consent_to_feature=VALUES(consent_to_feature),status='pending'");
        mysqli_stmt_bind_param($feedback, 'isiiisi', $postedOrderId, $email, $food, $service, $ordering, $comment, $consent); mysqli_stmt_execute($feedback);
        if ($ownedOrder['status'] === 'delivered') orderTransition($postedOrderId, 'completed', 'customer', $email, 'Customer confirmed delivery received');
        $_SESSION['delivery_feedback_notice'] = 'Thank you for confirming your delivery and sharing your feedback.';
    }
    header('Location: track-order.php?order=' . $postedOrderId); exit;
