$ordersStmt = mysqli_prepare($conn, 'SELECT o.orderid,f.total_amount,t.status,t.updated_at FROM orders o LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN order_tracking t ON t.orderid=o.orderid WHERE o.email=? ORDER BY o.orderid DESC');
mysqli_stmt_bind_param($ordersStmt, 's', $email); mysqli_stmt_execute($ordersStmt);
$customerOrders = mysqli_fetch_all(mysqli_stmt_get_result($ordersStmt), MYSQLI_ASSOC);
if ($orderId) { $stmt = mysqli_prepare($conn, 'SELECT o.orderid,o.address,f.total_amount,p.payment_method,t.status,t.updated_at FROM orders o LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN order_payments p ON p.orderid=o.orderid LEFT JOIN order_tracking t ON t.orderid=o.orderid WHERE o.orderid=? AND o.email=? LIMIT 1'); mysqli_stmt_bind_param($stmt, 'is', $orderId, $email); }
else { $stmt = mysqli_prepare($conn, 'SELECT o.orderid,o.address,f.total_amount,p.payment_method,t.status,t.updated_at FROM orders o LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN order_payments p ON p.orderid=o.orderid LEFT JOIN order_tracking t ON t.orderid=o.orderid WHERE o.email=? ORDER BY o.orderid DESC LIMIT 1'); mysqli_stmt_bind_param($stmt, 's', $email); }
mysqli_stmt_execute($stmt); $order = mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));
$steps = array('placed'=>array('Order placed','bi-receipt'),'confirmed'=>array('Confirmed','bi-patch-check'),'preparing'=>array('Preparing','bi-fire'),'ready_for_pickup'=>array('Ready for pickup','bi-bag-check'),'rider_assigned'=>array('Rider assigned','bi-person-check'),'picked_up'=>array('Picked up','bi-bag-check-fill'),'out_for_delivery'=>array('Out for delivery','bi-truck'),'delivered'=>array('Delivered','bi-house-check'),'completed'=>array('Completed','bi-check2-circle')); $rank = array_flip(array_keys($steps));
$history = array(); if ($order) { $historyStmt = mysqli_prepare($conn, 'SELECT status,note,created_at FROM order_status_history WHERE orderid=? ORDER BY created_at DESC,history_id DESC'); mysqli_stmt_bind_param($historyStmt, 'i', $order['orderid']); mysqli_stmt_execute($historyStmt); $history = mysqli_fetch_all(mysqli_stmt_get_result($historyStmt), MYSQLI_ASSOC); }
$deliveryFeedback = null; if ($order) { $feedbackStmt = mysqli_prepare($conn, 'SELECT feedback_id,receipt_confirmed,status FROM delivery_feedback WHERE orderid=? AND customer_email=? LIMIT 1'); mysqli_stmt_bind_param($feedbackStmt, 'is', $order['orderid'], $email); mysqli_stmt_execute($feedbackStmt); $deliveryFeedback = mysqli_fetch_assoc(mysqli_stmt_get_result($feedbackStmt)); }
$deliveryNotice = $_SESSION['delivery_feedback_notice'] ?? ''; unset($_SESSION['delivery_feedback_notice']);
$statusCopy = array('placed'=>'Your order has been received and is waiting for restaurant confirmation.','confirmed'=>'The restaurant has accepted your order.','preparing'=>'The kitchen is preparing your food.','ready_for_pickup'=>'Your food is ready for the delivery partner.','rider_assigned'=>'A delivery partner has been assigned to your order.','picked_up'=>'Your delivery partner has collected the order.','out_for_delivery'=>'Your order is on the way to your delivery address.','delivered'=>'Your order has been delivered. Enjoy your meal!','completed'=>'This order is complete. Thank you for choosing Foodera.','cancelled'=>'This order was cancelled. Check My Orders for cancellation and refund details.');
$methodLabels = array('cod'=>'Cash on delivery','upi'=>'UPI','card'=>'Card','netbanking'=>'Net banking');
$pageTitle = 'Track Delivery'; $activePage = 'orders'; $bodyClass = 'track-order-page'; $pageStyles = array('css/track-order.css','css/track-order-switcher.css','css/track-order-management.css','css/track-order-polish.css','css/delivery-feedback.css'); include __DIR__ . '/includes/public-header.php';
