<main class="track-order-main"><header class="track-order-heading"><div><p>Delivery status</p><h1>Track your order</h1></div><a href="order-history.php"><i class="bi bi-receipt-cutoff" aria-hidden="true"></i>My orders</a></header><?php if (count($customerOrders) > 1) { ?><nav class="track-order-switcher" aria-label="Choose an order to track"><span><?php echo count($customerOrders); ?> orders</span><?php foreach ($customerOrders as $customerOrder) { $switchStatus = $customerOrder['status'] ?: 'placed'; ?><a href="track-order.php?order=<?php echo (int)$customerOrder['orderid']; ?>"<?php echo $order && (int)$order['orderid'] === (int)$customerOrder['orderid'] ? ' aria-current="page"' : ''; ?>><strong>#<?php echo (int)$customerOrder['orderid']; ?></strong><small><?php echo htmlspecialchars(ucwords(str_replace('_',' ',$switchStatus)),ENT_QUOTES,'UTF-8'); ?> · Rs <?php echo number_format((float)$customerOrder['total_amount']); ?></small></a><?php } ?></nav><?php } ?><?php if (!$order) { ?><section class="track-order-empty"><i class="bi bi-truck" aria-hidden="true"></i><h2>No order to track</h2><p>Place an order first, then delivery updates will appear here.</p><a href="menu.php">Browse menu</a></section><?php } else { $status = $order['status'] ?: 'placed'; $currentRank = $rank[$status] ?? 0; ?><section class="track-status-hero<?php echo $status === 'cancelled' ? ' is-cancelled' : ''; ?>"><div class="track-status-icon"><i class="bi <?php echo $status === 'cancelled' ? 'bi-x-lg' : ($steps[$status][1] ?? 'bi-receipt'); ?>" aria-hidden="true"></i></div><div><p>Order #<?php echo (int) $order['orderid']; ?></p><h2><?php echo htmlspecialchars($status === 'cancelled' ? 'Order cancelled' : ($steps[$status][0] ?? 'Order placed'), ENT_QUOTES, 'UTF-8'); ?></h2><span><?php echo htmlspecialchars($statusCopy[$status] ?? $statusCopy['placed'], ENT_QUOTES, 'UTF-8'); ?></span></div><strong>Rs <?php echo number_format((float) ($order['total_amount'] ?? 0)); ?></strong></section><?php if ($status === 'cancelled') { ?><section class="track-cancelled"><i class="bi bi-info-circle" aria-hidden="true"></i><div><strong>Cancellation and refund details</strong><p>Any eligible refund is visible in your order record.</p></div><a href="order-history.php?order=<?php echo (int) $order['orderid']; ?>">View order</a></section><?php } else { ?><section class="track-panel"><div class="track-panel-heading"><div><h2>Delivery progress</h2><p>We will update this timeline as your order moves forward.</p></div><span><?php echo $currentRank; ?> of <?php echo count($steps); ?> steps</span></div><ol class="track-timeline"><?php foreach ($steps as $key => $step) { $complete = $rank[$key] <= $currentRank; ?><li class="<?php echo $complete ? 'is-complete' : ''; ?> <?php echo $key === $status ? 'is-current' : ''; ?>"><i class="bi <?php echo $step[1]; ?>" aria-hidden="true"></i><span><?php echo $step[0]; ?></span></li><?php } ?></ol></section><?php } ?><div class="track-info-grid"><section class="track-info-card"><i class="bi bi-geo-alt" aria-hidden="true"></i><div><span>Delivering to</span><strong><?php echo htmlspecialchars($order['address'], ENT_QUOTES, 'UTF-8'); ?></strong></div></section><section class="track-info-card"><i class="bi bi-credit-card" aria-hidden="true"></i><div><span>Payment method</span><strong><?php echo htmlspecialchars($methodLabels[$order['payment_method']] ?? 'Payment pending', ENT_QUOTES, 'UTF-8'); ?></strong></div></section></div><section class="track-activity"><div class="track-panel-heading"><div><h2>Order activity</h2><p>Latest updates from Foodera.</p></div><a href="order-history.php?order=<?php echo (int) $order['orderid']; ?>">View order details <i class="bi bi-arrow-right" aria-hidden="true"></i></a></div><ol><?php if ($history) { foreach ($history as $event) { ?><li><i class="bi bi-check2" aria-hidden="true"></i><div><strong><?php echo htmlspecialchars(ucwords(str_replace('_', ' ', $event['status'])), ENT_QUOTES, 'UTF-8'); ?></strong><?php if ($event['note']) { ?><p><?php echo htmlspecialchars($event['note'], ENT_QUOTES, 'UTF-8'); ?></p><?php } ?><time><?php echo htmlspecialchars(date('d M Y, h:i A', strtotime($event['created_at'])), ENT_QUOTES, 'UTF-8'); ?></time></div></li><?php } } else { ?><li><i class="bi bi-clock-history" aria-hidden="true"></i><div><strong><?php echo htmlspecialchars($steps[$status][0] ?? 'Order placed', ENT_QUOTES, 'UTF-8'); ?></strong><time><?php echo htmlspecialchars(date('d M Y, h:i A', strtotime($order['updated_at'] ?? 'now')), ENT_QUOTES, 'UTF-8'); ?></time></div></li><?php } ?></ol></section></main>
<?php } ?>
<?php if ($deliveryNotice !== '') { ?><div class="delivery-feedback-toast" role="status"><?php echo htmlspecialchars($deliveryNotice, ENT_QUOTES, 'UTF-8'); ?></div><?php } ?>
<?php if ($order && ($order['status'] ?? '') === 'delivered' && empty($deliveryFeedback['receipt_confirmed'])) { ?><dialog class="delivery-feedback-dialog" id="delivery-feedback-dialog"><section><p class="delivery-feedback-kicker">Delivery complete</p><h2>Have you received your order?</h2><p>Please confirm only after checking that the order has reached you.</p><div class="delivery-feedback-actions"><button type="button" class="delivery-feedback-primary" data-received>Yes, I received it</button><button type="button" class="delivery-feedback-problem" data-problem>I have a problem</button></div><form method="post" class="delivery-feedback-form" data-feedback-form hidden><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($_SESSION['delivery_feedback_csrf'], ENT_QUOTES, 'UTF-8'); ?>"><input type="hidden" name="orderid" value="<?php echo (int)$order['orderid']; ?>"><input type="hidden" name="delivery_action" value="confirm"><h3>Thank you for choosing Foodera</h3><p>Your ratings help us improve food quality, delivery service, and ordering.</p><label>Food quality <select name="food_rating" required><option value="">Select rating</option><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Average</option><option value="2">2 - Poor</option><option value="1">1 - Very poor</option></select></label><label>Delivery service <select name="service_rating" required><option value="">Select rating</option><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Average</option><option value="2">2 - Poor</option><option value="1">1 - Very poor</option></select></label><label>Ordering experience <select name="ordering_rating" required><option value="">Select rating</option><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Average</option><option value="2">2 - Poor</option><option value="1">1 - Very poor</option></select></label><label>Comment <textarea name="comment" maxlength="1000" rows="3" placeholder="Optional feedback"></textarea></label><label class="delivery-feedback-consent"><input type="checkbox" name="consent_to_feature" value="1"> I agree Foodera may use this review, after admin approval, as a testimonial to improve and promote its services.</label><button class="delivery-feedback-primary" type="submit">Submit feedback</button></form><form method="post" class="delivery-feedback-form" data-problem-form hidden><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($_SESSION['delivery_feedback_csrf'], ENT_QUOTES, 'UTF-8'); ?>"><input type="hidden" name="orderid" value="<?php echo (int)$order['orderid']; ?>"><input type="hidden" name="delivery_action" value="problem"><h3>We are sorry there is a problem</h3><p>Tell us what happened and Foodera support will receive a ticket.</p><label>What went wrong?<textarea name="problem_message" maxlength="1000" rows="4" required placeholder="Missing item, damaged food, wrong order, delivery concern..."></textarea></label><button class="delivery-feedback-primary" type="submit">Raise support ticket</button><button type="button" class="delivery-feedback-link" data-back>Back</button></form></section></dialog><script>(()=>{const dialog=document.querySelector('#delivery-feedback-dialog');if(!dialog)return;const feedback=dialog.querySelector('[data-feedback-form]'),problem=dialog.querySelector('[data-problem-form]');dialog.showModal();dialog.querySelector('[data-received]').addEventListener('click',()=>{feedback.hidden=false;problem.hidden=true;});dialog.querySelector('[data-problem]').addEventListener('click',()=>{problem.hidden=false;feedback.hidden=true;});dialog.querySelector('[data-back]').addEventListener('click',()=>{feedback.hidden=true;problem.hidden=true;});})();</script><?php } ?>
<script>
document.addEventListener('DOMContentLoaded', () => {
  const switcher = document.querySelector('.track-order-switcher');
  if (switcher) {
    const cards = [...switcher.querySelectorAll('a')];
    const controls = document.createElement('div');
    controls.className = 'track-order-controls';
    const group = text => { text = text.toLowerCase(); if (text.includes('cancelled')) return 'cancelled'; if (text.includes('completed') || text.includes('delivered')) return 'history'; return 'active'; };
    const activeCount = cards.filter(card => group(card.textContent) === 'active').length;
    const historyCount = cards.length - activeCount;
    const selectedCard = cards.find(card => card.hasAttribute('aria-current'));
    const visibleStatus = (document.querySelector('.track-status-hero h2')?.textContent || '').toLowerCase();
    let view = /completed|delivered|cancelled/.test(visibleStatus) ? 'history' : (selectedCard && group(selectedCard.textContent) === 'history' ? 'history' : 'active');
    controls.innerHTML = '<div class="track-order-view-tabs" role="tablist" aria-label="Order tracking views"><button type="button" data-view="active" role="tab">Active tracking <span>' + activeCount + '</span></button><button type="button" data-view="history" role="tab">Tracking history <span>' + historyCount + '</span></button></div><div class="track-order-controls-fields"><input type="search" placeholder="Search order number" aria-label="Search orders"><select aria-label="Filter selected orders"><option value="all">All statuses</option><option value="placed">Order placed</option><option value="confirmed">Confirmed</option><option value="preparing">Preparing</option><option value="out_for_delivery">Out for delivery</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div>';
    switcher.before(controls);
    const empty = document.createElement('p'); empty.className = 'track-order-filter-empty'; empty.hidden = true; switcher.after(empty);
    const search = controls.querySelector('input'); const filter = controls.querySelector('select'); const tabs = [...controls.querySelectorAll('[data-view]')];
    const update = () => {
      const term = search.value.trim().toLowerCase(); const selected = filter.value; let visible = 0;
      tabs.forEach(tab => tab.setAttribute('aria-selected', String(tab.dataset.view === view)));
      cards.forEach(card => { const text = card.textContent.toLowerCase(); const state = group(text); const matchesStatus = selected === 'all' || text.includes(selected.replaceAll('_', ' ')); const show = state === view && matchesStatus && (!term || text.includes(term)); card.hidden = !show; if (show) visible++; });
      empty.hidden = visible > 0; empty.textContent = 'No ' + (view === 'active' ? 'active tracking orders' : 'history records') + ' match this search or filter.';
    };
    tabs.forEach(tab => tab.addEventListener('click', () => { view = tab.dataset.view; filter.value = 'all'; update(); }));
    search.addEventListener('input', update); filter.addEventListener('change', update); update();
  }

  const progress = document.querySelector('.track-panel');
  if (progress) {
    const heading = progress.querySelector('.track-panel-heading');
    const toggle = document.createElement('button'); toggle.type = 'button'; toggle.className = 'track-collapse-button';
    const completed = /completed|delivered|cancelled/i.test(document.querySelector('.track-status-hero h2')?.textContent || '');
    progress.classList.toggle('is-collapsed', completed);
    toggle.textContent = completed ? 'Show progress' : 'Hide progress';
    toggle.setAttribute('aria-expanded', String(!completed));
    toggle.addEventListener('click', () => { const collapsed = progress.classList.toggle('is-collapsed'); toggle.textContent = collapsed ? 'Show progress' : 'Hide progress'; toggle.setAttribute('aria-expanded', String(!collapsed)); });
    heading.append(toggle);
  }

  const activity = document.querySelector('.track-activity');
  const events = activity?.querySelectorAll('ol > li') || [];
  if (events.length > 4) {
    activity.classList.add('is-condensed');
    const button = document.createElement('button'); button.type = 'button'; button.className = 'track-more-button'; button.textContent = 'Show all ' + events.length + ' updates'; button.setAttribute('aria-expanded', 'false');
    button.addEventListener('click', () => { const condensed = activity.classList.toggle('is-condensed'); button.textContent = condensed ? 'Show all ' + events.length + ' updates' : 'Show fewer updates'; button.setAttribute('aria-expanded', String(!condensed)); });
    activity.querySelector('ol').after(button);
  }
  activity?.querySelectorAll('p').forEach(note => {
    if (/otp|customer phone|admin actor/i.test(note.textContent)) note.textContent = 'Delivery update recorded.';
  });
});
</script>
